INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(164000, 0, 0, 'My lord, Lord Servin Darengar, has been staying at Stormwind Keep for some time now. Seek him out in the House of Nobles. He is surrounded by vipers.', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Dharil Cohen'),
(164001, 0, 0, 'I believe I have made my stance clear. Trolls, bandits, Ealdir... what more must happen before we resolve to intervene?', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Servin Darengar'),
(164001, 1, 0, 'If we do nothing, there will be nothing left to rule! Tell me, do we only help the drowning if they still have the voice to beg?', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Servin Darengar'),
(164001, 2, 0, 'Lady Serenya\'s pride will be our undoing. We must—!', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Servin Darengar'),
(164001, 3, 0, 'Go to my family\'s estate in Scadeald and show my seal to my son, Arathon. The province has need of brave souls like you if we are to survive the tribulations of our time.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Servin Darengar'),
(164002, 0, 0, 'Scour the manor from top to bottom. Rip up the floorboards if you must. Lady Serenya has placed great expectations upon you.', 12, 0, 100, 0, 0, 0, 0, 0, 'captured in game'),
(164002, 1, 0, 'You! Yes, you. Get over here.', 12, 0, 100, 0, 0, 0, 0, 0, 'captured in game'),
(164004, 0, 0, 'For Scadeald!', 12, 0, 100, 0, 0, 0, 0, 0, 'Wild Ealdir'),
(164004, 0, 1, 'I\'ll fashion an axe from your bones.', 12, 0, 100, 0, 0, 0, 0, 0, 'Wild Ealdir'),
(164004, 0, 2, 'You\'ll be carrion for the crows.', 12, 0, 100, 0, 0, 0, 0, 0, 'Wild Ealdir'),
(164004, 0, 3, 'Morgwena will find a use for your spirit. We Ealdir waste nothing.', 12, 0, 100, 0, 0, 0, 0, 0, 'Wild Ealdir'),
(164005, 0, 0, 'Yes? Who goes there? Did I not give orders that I was not to be disturbed?', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 1, 0, 'You will find Sir Draewyn in the throne room, overseeing matters of war. He will know how to make use of a talent such as yours.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 2, 0, 'Do tell... what effect was this poison meant to have? Drowsiness? Paralysis? A touch of agitation? Perhaps a simple heart attack? I\'m dying of curiosity... or at least, I\'m supposed to be.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 3, 0, 'I have followed your steps through Scadeald with great interest; I have eyes and ears everywhere.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 4, 0, 'I know who sent you. That witch from Baile Escada has set my head as the price for her alliance, has she? Including this attempt, that makes three times they\'ve tried to poison me.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 5, 0, 'Yet, what transpired in Lordaeron will be a fond memory compared to the darkness Morgwena intends to unleash.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 6, 0, 'So, it has come to this. Alas! The Light knows we require Deirdre\'s aid to stop Morgwena. And I am prepared to pay the price it demands:', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 7, 0, 'My death.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 8, 0, 'Rest easy, $C. Tonight, the city shall mourn its Regent.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164006, 0, 0, 'Look for Captain Amros Dhagor in Dunshire, to the west of here. Present yourself as an envoy of Graysky.', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Draewyn Unthar'),
(164006, 1, 0, 'You will find Sergeant Windhelm at the Graysky Outpost on the Kingsway. He is a man of... a certain temperament. Do not take his words to heart.', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Draewyn Unthar'),
(164006, 2, 0, 'Though Cresthairn has its own bailiff, the townsfolk turn to Father Elroth when they seek guidance or comfort. He is a man of sound judgment. Whatever the source of his concern may be, take it seriously.', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Draewyn Unthar'),
(164006, 3, 0, 'The gates of this castle shall remain open to you, now and forever. Let it be known that I dub thee a Knight of Graysky.', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Draewyn Unthar'),
(164007, 0, 0, 'Watch yourself on the road, all right? I\'ve only just met you, so it\'s not that I care all that much, but the cargo is valuable. And Scadeald is so dangerous... mind your step!', 12, 0, 100, 0, 0, 0, 0, 0, 'Hilma Golar'),
(164010, 0, 0, 'You will find the mine by following the path that leads up the mountain. Discretion is your best weapon against the gnolls; when they attack in a pack, they are lethal.', 12, 0, 100, 0, 0, 0, 0, 0, 'Captain Amros Dhagor'),
(164010, 1, 0, 'Are you... sure? It is not common to see gnolls this far north, but the southern provinces are used to dealing with them. And I have never heard of a curse like that.', 12, 0, 100, 0, 0, 0, 0, 0, 'Captain Amros Dhagor'),
(164010, 2, 0, 'A witch? What you have in courage, you lack in good sense: everyone in Scadeald knows witches cannot be trusted. She could have cursed them herself, for all we know!', 12, 0, 100, 0, 0, 0, 0, 0, 'Captain Amros Dhagor'),
(164011, 0, 0, 'We are at war; showing mercy to the enemy is an act of treason. Draw your sword and sheath your ethics. Finish them all. Exterminate the trolls.', 12, 0, 100, 0, 0, 0, 0, 0, 'Sergeant Windhelm'),
(164012, 0, 0, 'This is a bloody mess. Word is going to get out, sooner or later. And then... Light help us!', 12, 0, 100, 0, 0, 0, 0, 0, 'Mountaineer Thandel - 175107 rewarded'),
(164012, 1, 0, 'Follow that trail to the mine and comb the place through. There\'s got to be life left in those pits. I refuse to believe the Ealdir managed to snatch every last one of \'em.', 12, 0, 100, 0, 0, 0, 0, 0, 'Mountaineer Thandel - 175108 accepted'),
(164012, 2, 0, 'There you go. I\'ve marked Laurelin and Telperion\'s camp on your map.', 12, 0, 100, 0, 0, 0, 0, 0, 'Mountaineer Thandel - 175111 accepted'),
(164013, 0, 0, 'Oh, welcome. I am afraid there will be no sermon today. I shall not be holding mass for some time, truth be told.', 12, 0, 100, 0, 0, 0, 0, 1, 'Father Elroth - Greets players'),
(164013, 1, 0, 'The stairs to the crypts are over there, to my left. Be careful down there. You will find undead... but there may be something even worse.', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Elroth - On Noises Below accepted'),
(164014, 0, 0, 'The Hallowind Hanging Abbey is the most sacred site in all of Scadeald, and one of the kingdom\'s most vital points of pilgrimage. It goes without saying, but when you present yourself to Father Amrod, show him the proper respect.', 12, 0, 100, 0, 0, 0, 0, 0, 'Chaplain Conther'),
(164017, 0, 0, 'Proceed with caution in your journey.', 12, 0, 100, 0, 0, 0, 0, 0, 'Guard Dornhelm - A Sword for the North rewarded'),
(164020, 0, 0, 'Got any tobacco in those bags?', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Bandit'),
(164020, 0, 1, 'That merchant already paid... now it\'s your turn!', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Bandit'),
(164020, 0, 2, 'The king doesn\'t look north.', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Bandit'),
(164020, 0, 3, 'The Defias are a joke compared to us.', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Bandit'),
(164021, 0, 0, 'Another hero who\'s strayed from the road.', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Marauder'),
(164021, 0, 1, 'What are you doing here!?', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Marauder'),
(164021, 0, 2, 'Neither Ealdir nor of the kingdom. Free!', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Marauder'),
(164021, 0, 3, 'There\'s no king that matters here!', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Marauder'),
(164022, 0, 0, 'As long as there are murlocs in the lake, it doesn\'t matter how many times I cast my line...', 12, 0, 100, 0, 0, 0, 0, 0, 'Edrin Salmear'),
(164026, 0, 0, 'Ah, and don\'t open the flask yet!', 12, 0, 100, 0, 0, 0, 0, 0, 'Little Mickey'),
(164032, 0, 0, 'That man; well, what remains of him: Alto Bilberg. I know him, you know? Many years ago, when his daughter fell ill, he came here and accused me of hexing her. He threatened to burn my shack to the ground.', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164032, 1, 0, 'So let me ask again: why should I help them? Because it is the \'right\' thing to do? I learned long ago not to be guided by what is right, but by what is of interest.', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164032, 2, 0, 'Look for the sprites among the flowers. Give them a good shake, and they\'ll appear in a heartbeat to annoy the life out of you. You\'ll see just how \'fun\' they are.', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164032, 3, 0, 'The Three Sisters, eh? Few have seen them; to many, they\'re little more than legend. Never fear; I\'ll give you my blessing. If you don\'t end up dead, I hope you\'ll have a kind word for me before them.', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164032, 4, 0, 'I believe there is someone who might be able to help. It will be difficult to reach her, but you have already shown you are willing to risk your neck for these people. Listen closely:', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164033, 0, 0, 'Have fun with the Triple Sisters!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164033, 0, 1, 'Fool! I learned my craft from Cathbad himself!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164033, 0, 2, 'Your blood shall fertilize these lands.', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164033, 0, 3, 'You have chosen death, then.', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164033, 0, 4, 'Spirits, I dedicate this death to you!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164034, 0, 0, 'A true sweet tooth wants to try the very famous Dunshire cake!', 12, 0, 100, 0, 0, 0, 0, 0, 'Hestwin Honeycrust'),
(164034, 1, 0, 'Ask Innkeeper Miralda for plenty of milk! We need it for the cake!', 12, 0, 100, 0, 0, 0, 0, 0, 'Hestwin Honeycrust'),
(164034, 2, 0, 'I just need a bit of time to bake the pie. Patience, patience!', 12, 0, 100, 0, 0, 0, 0, 0, 'Hestwin Honeycrust'),
(164034, 3, 0, 'All done! The Dunshire pie is ready.', 12, 0, 100, 0, 0, 0, 0, 0, 'Hestwin Honeycrust'),
(164035, 0, 0, 'Turn the crank with all your might! Don\'t stop!', 12, 0, 100, 0, 0, 0, 0, 0, 'Miller Bartren'),
(164035, 1, 0, 'That\'s it! The flour is turning out perfectly fine.', 12, 0, 100, 0, 0, 0, 0, 0, 'Miller Bartren'),
(164035, 2, 0, 'Marvelous! Not even a strong gust of wind would do it better.', 12, 0, 100, 0, 0, 0, 0, 0, 'Miller Bartren'),
(164035, 3, 0, 'You\'ve kept that mill spinning like a dozen oxen! Now, enjoy the pie!', 12, 0, 100, 0, 0, 0, 0, 0, 'Miller Bartren'),
(164037, 0, 0, 'Remember: seek out Haldin Greensong at the Sanctuary. And tell him that you come on my behalf.', 12, 0, 100, 0, 0, 0, 0, 0, 'Darond'),
(164043, 0, 0, 'Morgwena will find a use for your spirit. We Ealdir waste nothing.', 12, 0, 100, 0, 0, 0, 0, 0, 'Jagged Cave Ealdir'),
(164043, 0, 1, 'I\'ll fashion an axe from your bones.', 12, 0, 100, 0, 0, 0, 0, 0, 'Jagged Cave Ealdir'),
(164045, 0, 0, 'Curse you! Curse every last one of you!', 12, 0, 100, 0, 0, 0, 0, 1, 'Cairn'),
(164045, 1, 0, 'I killed him. Yes. I killed my brother. That traitor... he\'s better off dead.', 12, 0, 100, 0, 0, 0, 0, 0, 'Cairn'),
(164045, 2, 0, 'Go on ahead. It will be some time before I return to Cresthairn, I think. I\'ll wait for things to settle down.', 12, 0, 100, 0, 0, 0, 0, 0, 'Cairn'),
(164047, 0, 0, 'Halt.', 14, 0, 100, 0, 0, 0, 0, 0, 'Raigh Anramor - disguised player approaches'),
(164048, 0, 0, 'Well, what do we have here? Do you truly believe you can steal the title of Chieftain of Ealdmaine from me? Ha!', 14, 0, 100, 0, 0, 0, 0, 0, 'Cragarn - aggro'),
(164048, 1, 0, 'You shall serve as a lesson to the others.', 14, 0, 100, 0, 0, 0, 0, 0, 'Cragarn - first combat line'),
(164048, 2, 0, 'I will have you flayed. The witch shall sew me a loincloth from your skin!', 14, 0, 100, 0, 0, 0, 0, 0, 'Cragarn - second combat line'),
(164048, 3, 0, 'Oh, Spirits... have mercy... on my... soul...', 14, 0, 100, 0, 0, 0, 0, 0, 'Cragarn - death'),
(164049, 0, 0, 'Get back! Have you lost your mind?', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - disguised player too close'),
(164049, 1, 0, 'Get back! Have you lost your mind?', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - aggro'),
(164049, 1, 1, 'What do you think you\'re doing?', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - aggro'),
(164049, 1, 2, 'That\'s going to cost you dearly.', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - aggro'),
(164049, 1, 3, 'If you want to train, find an aspirant!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - aggro'),
(164050, 0, 0, 'Psst! Yes, you! Come here!', 12, 0, 100, 0, 0, 0, 0, 0, 'Randec'),
(164050, 1, 0, 'Let me see you. Good, good. It\'ll pass. Just make sure to keep a sour face. Those Ealdir wear that expression all the time.', 12, 0, 100, 0, 0, 0, 0, 0, 'Randec'),
(164055, 0, 0, 'Thank you... Ugh!', 12, 0, 100, 0, 0, 0, 0, 0, 'Wounded Graysky Soldier'),
(164056, 0, 0, 'Thank you... Ugh!', 12, 0, 100, 0, 0, 0, 0, 0, 'Wounded Graysky Soldier'),
(164060, 0, 0, 'And for pity\'s sake, watch your step in there! The last thing I need is to have to go saving your skin on top of my own duties.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lieutenant Frieren'),
(164060, 1, 0, 'It will be a long time before the trolls recover from the blow you dealt at Zuramunda. Never again will they dare to underestimate us.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lieutenant Frieren'),
(164060, 2, 0, 'The hostages you rescued have taken refuge in the old watchtower. Go to them and make sure they\'re safe.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lieutenant Frieren'),
(164061, 0, 0, 'De Princess got powerful allies...', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 1, 'For Mexitla!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 2, 'Ya children gonna grow up orphans...', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 3, 'For de Frostmane!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 4, 'I bet ya taste good... let me have a bite!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 5, 'I got de blessin\' of de Loa!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 6, 'I won\'t leave a body for ya loved ones to weep over...', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 7, 'For de Ancient Empire!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 8, 'Druk\'thar endures!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 9, 'Die!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 10, 'We gonna kill ya all. Startin\' wit\' you!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 11, 'Ya death brings us closer to de Glory Days!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 12, 'What made ya think ya could beat me?', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 13, 'No mercy!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 14, 'I\'ve killed dozens of ya kind... why ya don\'t just give up?', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 15, 'Victory for Mexitla!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 16, 'I\'m gonna eat it all! Bones included!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 17, 'I ain\'t afraid of ya!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 18, 'Dese lands be ours!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 19, 'Ya gonna pay for what ya ancestors stole from us!', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 1, 0, 'One less thing to worry about.', 14, 0, 100, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
