(164076, 0, 2, 'Rivers of blood shall flow.', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 3, 'City-dwelling scum.', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 4, 'Freedom for Scadeald!', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 5, 'The Witch will take your children!', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 6, 'Death to the Kingdom!', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 7, 'You are all intruders in our land.', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 8, 'Victory for the Ealdir!', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 9, 'Scadeald shall be free!', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164077, 0, 0, 'Come and get me, if you have the stones!', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad'),
(164077, 1, 0, 'I\'ll rip the heart from your chest while it still beats. My blood-stained maw will be the last thing you ever see.', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(164077, 1, 1, 'Mercenary scum!', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad'),
(164077, 1, 2, 'Is that the best you can do?', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad'),
(164077, 2, 0, 'You are nothing but... a lowly sell-sword...', 12, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad'),
(164079, 0, 0, 'I always say some god must\'ve put \'em together backwards: the top half shouldn\'t have been an eagle, but a lion, \'cause they eat like one!', 12, 0, 100, 0, 0, 0, 0, 0, 'Gryphon Keeper Bromli - Gryphon Appetizer rewarded'),
(164079, 1, 0, 'As an expert in the field, take my word for it: it won\'t be long before these gryphons take a likin\' to ye. In fact...', 12, 0, 100, 0, 0, 0, 0, 0, 'Gryphon Keeper Bromli - Nests and Feathers rewarded'),
(164081, 0, 0, 'Have fun with the Triple Sisters!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164081, 0, 1, 'Fool! I learned my craft from Cathbad himself!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164081, 0, 2, 'Your blood shall fertilize these lands.', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164081, 0, 3, 'You have chosen death, then.', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164081, 0, 4, 'Spirits, I dedicate this death to you!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164161, 0, 0, 'A savage howl echoes nearby. %s has appeared', 41, 0, 100, 0, 0, 0, 0, 2, 'Skymaw - On Respawn - zone announcement'),
(164172, 0, 0, 'Hestwin says the dough has to “breathe its own magic”...', 12, 0, 100, 0, 0, 0, 0, 0, 'Geralda'),
(164172, 1, 0, 'I think he just likes to make you wait while you’re hungry.', 12, 0, 100, 0, 0, 0, 0, 0, 'Geralda'),
(164172, 2, 0, 'But honestly, the wait is worth it.', 12, 0, 100, 0, 0, 0, 0, 0, 'Geralda'),
(164196, 0, 0, 'Understand this: there is no Good without Truth, nor Truth without Revelation. Man is fallible, and his senses but mere mirages.', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - sermon 1'),
(164196, 1, 0, 'No matter how noble your heart may be, if your blade obeys a falsehood, you serve not the Light, but the Shadow. Outside of Truth, all virtue is but sin in disguise.', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - sermon 2'),
(164196, 2, 0, 'Fear not, $gson:daughter; weakness is also a sin. And there is no shame in chastising sinners. The Light has no need for cowards as its ambassadors.', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - 175013 accepted'),
(164196, 3, 0, 'May the Light guide your steps, my $gson:daughter;. And may those abominations learn to fear your righteous wrath.', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - 175014 accepted'),
(164196, 4, 0, 'Ah, here $ghe:she; is! The instrument of the Light. Its weapon of justice. You have exterminated them, haven\'t you? You wouldn\'t have returned otherwise.', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - player returns from Grimepit'),
(164197, 0, 0, 'I have not lived up to what the Light expects of me.', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - pre-duel'),
(164197, 0, 1, 'I fear I\'ve given all... and it\'s still not enough.', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - pre-duel'),
(164197, 1, 0, 'I will not let my faith falter.', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 1, 1, 'Today I will remember why I swore to serve.', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 1, 2, 'I cannot fail my oath!', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 1, 3, 'Let my blade speak for my oath!', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 1, 4, 'You\'ll see if my devotion is enough!', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 2, 0, 'I will redeem this failure. I promise you.', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - defeated'),
(164197, 2, 1, 'May the Light forgive me.', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - defeated'),
