INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES
(100705, 0, 0, '(Quest)I\'ve come to help with your training. Prepare for combat!', 0, 1, 1, 0, 0, 0, 0, '', 0, NULL),
(100708, 0, 0, 'Are you in charge of Dun Kazad\'s armies?', 0, 1, 1, 1200437, 0, 0, 0, '', 0, 0),
(100708, 1, 0, 'What does Dun Kazad mean?', 0, 1, 1, 1200439, 0, 0, 0, '', 0, 0),
(100710, 0, 0, '|cFF0000FF(Quest)|rAccording to the Church of the Holy Light, what will become of Holdor\'s soul?', 0, 1, 1, 100712, 0, 0, 0, '', 0, 0),
(100710, 1, 0, '|cFF0000FF(Quest)|rWhat are the tenets of the Holy Light?', 0, 1, 1, 100713, 0, 0, 0, '', 0, 0),
(100710, 2, 0, '|cFF0000FF(Quest)|rYou may begin', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100711, 0, 0, '|cFF0000FF(Quest)|rAccording to the Creed of the Pantheon, what will become of Holdor\'s soul?', 0, 1, 1, 100714, 0, 0, 0, '', 0, 0),
(100711, 1, 0, '|cFF0000FF(Quest)|rWhat are the tenets of the Creed of the Pantheon?', 0, 1, 1, 100715, 0, 0, 0, '', 0, 0),
(100711, 2, 0, '|cFF0000FF(Quest)|rYou may begin', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100716, 0, 0, '|cFF0000FF(Quest)|rBeorn sends me. The Stonefist family has decided to convert to the Holy Light', 0, 1, 1, 100718, 0, 0, 0, '', 0, 0),
(100717, 0, 0, '|cFF0000FF(Quest)|rKhazemil sends me. The Stonefist family has decided to convert to the Creed of the Pantheon', 0, 1, 1, 100719, 0, 0, 0, '', 0, 0),
(100722, 0, 0, '|cFF0000FF(Quest)|rI seek the Three Sisters, and I need the blessing of three witches to reach them.', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100725, 0, 0, 'I wish to return.', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100727, 0, 0, '|cFF0000FF(Quest)|rI was sent by Alanna. <You recount the events in the crypt: Alanna\'s resurrection as undead, and her plea for help.>', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100728, 0, 0, '<You tell him the truth about the gnolls, but avoid mentioning the witch\'s involvement.>', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100728, 1, 0, '<You tell him about the witch, Beldred, and the gnolls\' curse in every detail.>', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
